// エクスポート名・振る舞いだけは保持しなければならない
// （Generation 0で確定した固定契約）。

import { WorldProtocol } from "../../schema";
import { WorldState, createInitialWorld } from "./world";
import { advanceFen1, advanceFen2, lockFenZef } from "./fen/rules";
import { advanceOsk1 } from "./osk/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceVok1, advanceVok2 } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";

type WorldOperation = (world: WorldState) => WorldState;

const operations: Record<string, WorldOperation> = {
  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceFen1,
  advanceFen2,
  lockFenZef,
};

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(state: WorldState, operationDisplayName: string) {
    const operation = operations[operationDisplayName];
    if (!operation) {
      return {
        success: false as const,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return { success: true as const, newState: operation(state) };
    } catch (error) {
      return {
        success: false as const,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    switch (entityDisplayName) {
      case "Vok":
        return state.vok;
      case "Zef":
        return state.zef;
      case "Tal":
        return state.tal;
      case "Fen":
        return state.fen;
      case "Osk":
        return state.osk;
      default:
        return "unknown";
    }
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return {
      Vok: state.vok,
      Zef: state.zef,
      Tal: state.tal,
      Fen: state.fen,
      Osk: state.osk,
    };
  },
};
